(81, 1, '2026-10-09 20:37:07', '2026-10-09 17:37:07', '.site-header {\n    position: sticky;\n    top: 0;\n    z-index: 999;\n    background-color: #ffffff;\n    box-shadow: 0 2px 5px rgba(0,0,0,0.1);\n}\n.woocommerce-breadcrumb {\n    display: none;\n}\n.woocommerce-result-count {\n    display: none;\n}\n.woocommerce-ordering {\n    display: none;\n}\n.woocommerce a.button,\n.woocommerce button.button,\n.woocommerce input.button,\n.woocommerce #respond input#submit,\n.woocommerce .single_add_to_cart_button,\n.woocommerce ul.products li.product .button,\n.woocommerce div.product form.cart .button,\n.woocommerce-checkout #place_order,\n.woocommerce .coupon button,\n.woocommerce-cart .wc-proceed-to-checkout a.checkout-button,\n.woocommerce-checkout .button.alt,\n.woocommerce #payment #place_order,\n.woocommerce-cart .checkout-button,\n.woocommerce .cart .button,\n.woocommerce .cart input.button {\n    background-color: #F78DA7 !important;\n    color: #ffffff !important;\n    border-color: #F78DA7 !important;\n}\n\n.woocommerce a.button:hover,\n.woocommerce button.button:hover,\n.woocommerce input.button:hover,\n.woocommerce #respond input#submit:hover,\n.woocommerce .single_add_to_cart_button:hover,\n.woocommerce ul.products li.product .button:hover,\n.woocommerce div.product form.cart .button:hover,\n.woocommerce-checkout #place_order:hover,\n.woocommerce .coupon button:hover,\n.woocommerce-cart .wc-proceed-to-checkout a.checkout-button:hover,\n.woocommerce-checkout .button.alt:hover,\n.woocommerce #payment #place_order:hover,\n.woocommerce-cart .checkout-button:hover,\n.woocommerce .cart .button:hover,\n.woocommerce .cart input.button:hover {\n    background-color: #E56B8A !important;\n    color: #ffffff !important;\n    border-color: #E56B8A !important;\n}\n\n.main-header-menu > .menu-item > .menu-link {\n    color: #333333 !important;\n}\n\n.main-header-menu > .menu-item > .menu-link:hover,\n.main-header-menu > .menu-item.current-menu-item > .menu-link,\n.main-header-menu > .menu-item.current-menu-ancestor > .menu-link {\n    color: #F78DA7 !important;\n}\n\n.main-header-menu .sub-menu,\n.main-header-menu .sub-menu .menu-link,\n.ast-header-break-point .main-header-menu,\n.ast-desktop .main-header-menu .sub-menu,\n.main-header-menu .sub-menu .menu-item > .menu-link {\n    background-color: #FFFFFF !important;\n    color: #333333 !important;\n}\n\n.main-header-menu .sub-menu .menu-link:hover,\n.main-header-menu .sub-menu .menu-item > .menu-link:hover {\n    background-color: #F5F5F5 !important;\n    color: #F78DA7 !important;\n}\n\n.woocommerce-message,\n.woocommerce-info,\n.woocommerce-error {\n    background-color: #F5F5F5 !important;\n    color: #333333 !important;\n    border-top-color: #ABB8C3 !important;\n}\n\n.woocommerce-message::before,\n.woocommerce-info::before,\n.woocommerce-error::before {\n    color: #ABB8C3 !important;\n}\n\n.woocommerce a:not(.button) {\n    color: #333333 !important;\n}\n\n.woocommerce a:not(.button):hover {\n    color: #F78DA7 !important;\n}\n\n.woocommerce input[type=\"text\"],\n.woocommerce input[type=\"email\"],\n.woocommerce input[type=\"tel\"],\n.woocommerce input[type=\"number\"],\n.woocommerce input[type=\"password\"],\n.woocommerce textarea,\n.woocommerce select {\n    border-color: #ABB8C3 !important;\n    background-color: #FFFFFF !important;\n    color: #333333 !important;\n}\n\n.woocommerce input:focus,\n.woocommerce textarea:focus,\n.woocommerce select:focus {\n    border-color: #F78DA7 !important;\n    outline-color: #F78DA7 !important;\n}\n\n.woocommerce-breadcrumb,\n.woocommerce-breadcrumb a {\n    color: #ABB8C3 !important;\n}\n\n.woocommerce-ordering select {\n    border-color: #ABB8C3 !important;\n    color: #333333 !important;\n}\n\n.woocommerce nav.woocommerce-pagination ul {\n    border: none !important;\n}\n\n.woocommerce nav.woocommerce-pagination ul li {\n    border: none !important;\n}\n\n.woocommerce nav.woocommerce-pagination ul li a,\n.woocommerce nav.woocommerce-